@Component("incident-entity-projector")
public class IncidentEntityProjector implements EntityProjector<Incident>{
		
	// core constructor
	public IncidentEntityProjector(ProjectorRegistry registry,
										IncidentRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Incident> getEntityClass() {
		return Incident.class;
	}

    /*
	 * Insert a Incident
	 * 
     * @param	entity Incident
     */
    public Incident create( Incident entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Incident
	 * 
     * @param	entity Incident
     */
    public Incident update( Incident entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Incident
	 * 
     * @param	id		UUID
     */
    public Incident delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Incident entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Claim
     * 
     * @param	parentId	UUID
     * @param	assignment 	Claim 
     * @return	Incident
     */
    public Incident assignClaim( UUID parentId, Claim assignment ) {
	    LOGGER.info("assigning Claim as " + assignment.toString() );

	    Incident parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Claim.class, assignment.getClaimId());

	    // ------------------------------------------
		// assign the Claim to the parent entity
		// ------------------------------------------ 
	    parentEntity.setClaim( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Claim
	 * 
	 * @param	parentId		UUID
	 * @return	Incident
	 */
	public Incident unAssignClaim( UUID parentId ) {
		Incident parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Claim on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Claim on the parent entithy
		// ------------------------------------------     
	    parentEntity.setClaim(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the InsuredObjects
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Incident
     */
    public Incident addToInsuredObjects( UUID parentId, InsuredObject addTo ) {
	    LOGGER.info("handling AssignInsuredObjectsToIncidentEvent - " );
	    
	    Incident parentEntity = repository.findById(parentId).get();
	    InsuredObject child = registry.project( InsuredObject.class, addTo.getInsuredObjectId());
	    
	    parentEntity.getInsuredObjects().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the InsuredObjects
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Incident
     */
	public Incident removeFromInsuredObjects( UUID parentId, InsuredObject removeFrom ) {
	    LOGGER.info("handling RemoveInsuredObjectsFromIncidentEvent " );
	
	    Incident parentEntity = repository.findById(parentId).get();
	    InsuredObject child = registry.project( InsuredObject.class, removeFrom.getInsuredObjectId());
	    
	    parentEntity.getInsuredObjects().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Incident via an FindIncidentQuery
     * @return 	query	FindIncidentQuery
     */
    @SuppressWarnings("unused")
    public Incident find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Incident - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Incidents
     *
     * @param	query	FindAllIncidentQuery 
     * @return 	List<Incident> 
     */
    @SuppressWarnings("unused")
    public List<Incident> findAll( FindAllIncidentQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Incident - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final IncidentRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(IncidentEntityProjector.class.getName());

}
